  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Telling Bible Stories in Spanish$j$, $j${"readings": [{"title": "Psalm 78 (King James Version)", "url": "/portal/bible/Psalms/78"}], "body": "Psalm 78:4 says, We will not hide them from their children, shewing to the generation to come the praises of the LORD, and his strength, and his wonderful works that he hath done. Telling the stories of God in Spanish lets you share them with a Spanish speaking child, neighbor or friend. You now have the tools: the preterite for events and the imperfect for the scene.\n\nUseful story words are la historia, el relato, el ángel, los pastores, el pastor, el rey, el profeta, el discípulo, el milagro, la cruz, la tumba, el cielo, la tierra, nació, murió, resucitó, dijo, creó, llamó and sanó.\n\nBuild a story in four steps. First, set the scene with the imperfect: Había un hombre que se llamaba Zaqueo, y era pequeño. Second, tell what happened with the preterite: Jesús pasó por la ciudad, vio a Zaqueo y le dijo que bajara. Third, show the result: Zaqueo recibió a Jesús con alegría. Fourth, state the lesson: Jesús vino a buscar y a salvar lo que se había perdido.\n\nWorked example: Dios creó los cielos y la tierra. Al principio todo estaba oscuro, pero Dios dijo: Sea la luz. Common mistake: using the present tense for a past story, or using a translation tool and copying it. Write the sentences yourself and have a fluent speaker or teacher check them.\n\nYour task: (1) Tell a Bible story of at least eight sentences in Spanish using both the preterite and the imperfect. (2) Underline each preterite and circle each imperfect.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Psalm 78:4 says, We will not hide them from their children, shewing to the generation to come the praises of the LORD. Telling Bible stories in Spanish is one way to do that.\n\nNow watch this. Story words: la historia, el ángel, los pastores, el rey, el profeta, el milagro, la cruz, la tumba. Verbs: nació, murió, resucitó, dijo, creó, llamó, sanó.\n\nBuild a story in four steps. Set the scene with the imperfect. Tell what happened with the preterite. Show the result. State the lesson.\n\nDios creó los cielos y la tierra. Todo estaba oscuro, pero Dios dijo: Sea la luz.\n\nWrite the story yourself, and have a fluent speaker check it.\n\nYour task is to tell a Bible story in eight Spanish sentences and mark each tense. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Telling Bible Stories in Spanish$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Prayer, Testimony and Hospitality$j$, $j${"readings": [{"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}], "body": "Philippians 4:6 says, Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. Many Spanish speaking believers pray out loud with great warmth, and you can learn to pray with them.\n\nIn Spanish prayers, believers usually address God with the familiar forms tú, te and ti as a sign of closeness and love. Useful phrases are Oremos (let us pray), Padre celestial, Señor Jesús, te damos gracias por, te pedimos que, bendice a, en el nombre de Jesús and amén. The phrase te pedimos que is followed by a special verb form called the subjunctive, which you will study in Spanish 3, so for now learn the phrases as a set: te pedimos que nos ayudes.\n\nA testimony tells what God has done. Use the imperfect and the preterite: Antes yo estaba perdido, pero un día encontré a Jesús, y ahora tengo paz. Add time words: antes, un día, ahora.\n\nHospitality uses formal courtesy. Bienvenido (to one man), bienvenida (to one woman) and bienvenidos (to a group). ¿Puedo orar por usted? ¿Necesita algo? Estamos para servirle. Gracias por visitarnos. Vuelva pronto.\n\nWorked example: Bienvenidos a nuestra iglesia. ¿Puedo orar por usted? Oremos: Padre celestial, te damos gracias por este día. En el nombre de Jesús, amén. Common mistake: praying with memorized words you do not understand. Learn what each phrase means.\n\nYour task: (1) Write a three sentence Spanish welcome for visitors. (2) Write a testimony of five sentences using antes, un día and ahora.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Philippians 4:6 says, In every thing by prayer and supplication with thanksgiving let your requests be made known unto God. Let us learn to pray in Spanish.\n\nNow watch this. Spanish believers usually address God as tú, a sign of closeness. Phrases: Oremos. Padre celestial. Te damos gracias por. Te pedimos que. En el nombre de Jesús. Amén.\n\nA testimony: Antes yo estaba perdido, pero un día encontré a Jesús, y ahora tengo paz.\n\nHospitality: Bienvenido, bienvenida, bienvenidos. ¿Puedo orar por usted? ¿Necesita algo? Estamos para servirle. Vuelva pronto.\n\nLearn what each phrase means before you use it.\n\nYour task is to write a welcome for visitors and a five sentence testimony. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Prayer, Testimony and Hospitality$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Writing Letters and Emails in Spanish$j$, $j${"readings": [{"title": "Romans 1 (King James Version)", "url": "/portal/bible/Romans/1"}], "body": "Romans 1:7 says, Grace to you and peace from God our Father, and from the Lord Jesus Christ. Paul began his letters with a greeting of blessing, and Spanish letters have clear openings and closings too.\n\nFor a formal letter or email, begin with Estimado señor García or Estimada señora López. Use a comma or a colon after the name. Open with Le escribo para... followed by your purpose: Le escribo para pedir información sobre su programa. Close with Atentamente, Cordialmente or Sinceramente, then your name.\n\nFor a friend or relative, begin with Querido Pedro or Querida abuela and close with Un abrazo, Con cariño or Tu amigo. Use tú forms and a warm tone. A common set phrase is Espero que estés bien, which means I hope you are well.\n\nWrite the date as day, month, year, with no capital letters for the month: 15 de noviembre de 2026. Write the subject line of an email in a few clear words: Solicitud de información.\n\nWorked example: Estimada señora López: Le escribo para dar las gracias por su visita a nuestra iglesia. Esperamos verla pronto. Atentamente, Ana Díaz. Common mistake: using tú in a formal letter or ending with an English closing. Match your closing to the greeting.\n\nYour task: (1) Write a formal email of five sentences asking for information about a program. (2) Write an informal note of five sentences to a friend.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Romans 1:7 says, Grace to you and peace from God our Father, and from the Lord Jesus Christ. Paul began his letters with a blessing.\n\nNow watch this. A formal letter begins with Estimado señor or Estimada señora. Say Le escribo para and give your purpose. Close with Atentamente, Cordialmente or Sinceramente.\n\nFor a friend, begin with Querido or Querida. Close with Un abrazo or Con cariño. Say Espero que estés bien.\n\nWrite the date as 15 de noviembre de 2026, with the month in small letters.\n\nMatch the closing to the greeting, and use usted in formal writing.\n\nYour task is to write a formal email and an informal note, five sentences each. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Writing Letters and Emails in Spanish$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Serving Neighbors, Interpreting Honestly and Next Steps$j$, $j${"readings": [{"title": "Matthew 25 (King James Version)", "url": "/portal/bible/Matthew/25"}], "body": "Matthew 25:40 says, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me. Your Spanish can be a gift of service, and the way to use it well is with honesty, humility and care.\n\nKnow your level. Traducir means to translate in writing, and interpretar means to interpret what is spoken. Interpreting is a professional skill. A church volunteer can greet, welcome, give directions and share simple information. For medical, legal, school or financial matters, always ask for a trained interpreter. Say Un momento, por favor, voy a buscar a un intérprete.\n\nPractical ways to serve are to greet visitors, help with a Spanish welcome sign (have a fluent speaker proofread it), host a conversation table, read Scripture aloud with a Spanish speaking friend, write a thank you note, and pray with neighbors. Always use respect: usted for elders and strangers, and a kind tone.\n\nTo keep growing, read a little every day. Listen to Spanish music or sermons, speak with a Spanish speaking friend, and keep a notebook of new words. In Spanish 3 you will study the subjunctive, the conditional and more.\n\nWorked example: Soy estudiante de español y me gustaría ayudar. Voy a buscar a alguien que pueda interpretar mejor. Common mistake: pretending to know more than you do. Honesty protects the people you serve.\n\nYour task: (1) Write a plan of five ways you will use Spanish to serve. (2) Write a goal for Spanish 3 in four Spanish sentences.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Matthew 25:40 says, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me. Your Spanish can be a gift of service.\n\nNow watch this. Traducir is to translate in writing. Interpretar is to interpret what is spoken. Interpreting is a professional skill.\n\nA volunteer can greet, welcome, give directions and share simple information. For medical, legal, school or financial matters, always ask for a trained interpreter. Say, Un momento, por favor, voy a buscar a un intérprete.\n\nWays to serve: greet visitors, help with a welcome sign that a fluent speaker has checked, host a conversation table, write thank you notes, and pray.\n\nKeep growing every day. Honesty protects the people you serve.\n\nYour task is to write a plan of five ways to serve and a goal for Spanish 3. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Serving Neighbors, Interpreting Honestly and Next Steps$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Faith, Letters and Serving Others$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. Matthew 25:40 says, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me.\n\nPart 1: Retell a Bible story in at least ten Spanish sentences using both the preterite and the imperfect.\nPart 2: Write a Spanish welcome for visitors of at least four sentences, a prayer phrase list of five phrases with meanings, and a testimony of five sentences.\nPart 3: Write a formal email and an informal note in Spanish, five sentences each, with correct openings and closings.\nPart 4: Explain the difference between traducir and interpretar, and describe when a volunteer should ask for a trained interpreter.\nPart 5: Describe three ways you can use Spanish to serve others honestly and respectfully.\nPart 6: Explain how Philippians 4:6, Psalm 78:4 and Matthew 25:40 shape your goals for using Spanish.", "rubric": "100 points. Part 1: 25 points. Part 2: 20 points. Part 3: 20 points. Part 4: 10 points. Part 5: 10 points. Part 6: 10 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Faith, Letters and Serving Others$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Words That Serve$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one person or group you would like to serve with Spanish, (2) shares at least three Spanish sentences you could say to them, (3) explains one limit of your Spanish and how you would handle it honestly, and (4) connects your answer to Matthew 25:40 or Philippians 4:6. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why does honesty about our abilities matter when we serve people in need?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Words That Serve$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Telling Bible Stories in Spanish$j$, $j${"questions": [{"q": "Dios creó el mundo uses the:", "options": ["Preterite", "Command", "Future", "Imperfect"]}, {"q": "Todo estaba oscuro describes:", "options": ["A sudden event", "The scene", "A command", "A future plan"]}, {"q": "Resucitó means:", "options": ["He died", "He was born", "He called", "He rose from the dead"]}, {"q": "When telling a Bible story in Spanish, you should:", "options": ["Copy a full translation tool output", "Use only the present tense", "Avoid Scripture", "Write it yourself and have it checked"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Telling Bible Stories in Spanish$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,3}'::int[], array[$j$Creó is a completed action.$j$,$j$The imperfect sets the scene.$j$,$j$Resucitar means to rise again.$j$,$j$Your own work, checked by a fluent speaker, builds skill.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Telling Bible Stories in Spanish$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Prayer, Testimony and Hospitality$j$, $j${"questions": [{"q": "Bienvenidos is said to:", "options": ["A group", "One man", "One woman", "A pet"]}, {"q": "Oremos means:", "options": ["I pray", "We pray often", "Let us pray", "We prayed"]}, {"q": "Antes yo estaba perdido uses the imperfect because it describes:", "options": ["A sudden event", "A command", "A future plan", "A past state"]}, {"q": "¿Puedo orar por usted? is:", "options": ["A request for money", "A command", "A past event", "A polite offer"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Prayer, Testimony and Hospitality$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,3}'::int[], array[$j$The ending os shows a group.$j$,$j$Oremos is the let us form of orar.$j$,$j$Estaba describes the condition before the change.$j$,$j$It offers prayer respectfully.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Prayer, Testimony and Hospitality$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Writing Letters and Emails in Spanish$j$, $j${"questions": [{"q": "A formal letter to a woman begins:", "options": ["Oye", "Querida amiga", "Hola, chica", "Estimada señora"]}, {"q": "Atentamente means:", "options": ["Sincerely", "Goodbye", "Thank you", "Welcome"]}, {"q": "The date 15 de noviembre de 2026 shows the order:", "options": ["Year, day, month", "Day, month, year", "Month, day, year", "Year, month, day"]}, {"q": "Un abrazo is used with:", "options": ["A stranger in a formal letter", "A government office", "A friend or relative", "A judge"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Writing Letters and Emails in Spanish$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,2}'::int[], array[$j$Estimada is formal.$j$,$j$Atentamente is a formal closing.$j$,$j$Spanish writes the day first.$j$,$j$It means a hug and is informal.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Writing Letters and Emails in Spanish$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Serving Neighbors, Interpreting Honestly and Next Steps$j$, $j${"questions": [{"q": "Interpretar means to:", "options": ["Interpret spoken words", "Sing", "Translate a book", "Ask a question"]}, {"q": "For medical or legal matters, a volunteer should:", "options": ["Ask for a trained interpreter", "Refuse to help", "Use only slang", "Guess the words"]}, {"q": "Un momento, por favor, voy a buscar a un intérprete means:", "options": ["I interpreted yesterday", "Please wait a year", "I am an interpreter", "One moment, please, I am going to find an interpreter"]}, {"q": "Matthew 25:40 teaches that serving others is like:", "options": ["Winning a contest", "Earning a grade", "Avoiding work", "Serving Christ"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Serving Neighbors, Interpreting Honestly and Next Steps$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,3}'::int[], array[$j$Interpretar is for spoken language.$j$,$j$Accuracy protects the person being served.$j$,$j$It politely asks for a professional.$j$,$j$Jesus said whatever we do for the least of these, we do for Him.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Serving Neighbors, Interpreting Honestly and Next Steps$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Faith, Letters and Serving Others$j$, $j${"questions": [{"q": "Bienvenida is said to:", "options": ["Nobody", "A group of men", "One woman", "One man"]}, {"q": "Te damos gracias means:", "options": ["They thank me", "Thank them", "I give you thanks", "We give you thanks"]}, {"q": "Estimado señor is used in a:", "options": ["Text to a friend", "Casual note", "Formal letter", "Birthday card to a sibling"]}, {"q": "Cordialmente is a:", "options": ["Command", "Formal closing", "Question", "Greeting"]}, {"q": "Resucitó is in the:", "options": ["Preterite", "Present", "Future", "Imperfect"]}, {"q": "Había un hombre is in the:", "options": ["Command", "Imperfect", "Future", "Preterite"]}, {"q": "To translate in writing, use:", "options": ["Estar", "Interpretar", "Viajar", "Traducir"]}, {"q": "A good practice for serving with Spanish is to:", "options": ["Be honest about your level", "Pretend to know everything", "Avoid greeting people", "Use only English"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Faith, Letters and Serving Others$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,1,0,1,3,0}'::int[], array[$j$The ending a shows a woman.$j$,$j$Damos is the nosotros form of dar.$j$,$j$Estimado is formal.$j$,$j$It is a formal closing similar to cordially.$j$,$j$It tells a completed action.$j$,$j$Había describes the scene.$j$,$j$Traducir is for written language.$j$,$j$Honesty protects the people you serve.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Faith, Letters and Serving Others$j$ on conflict (item_id) do nothing;
